import { expect, expectStatus, test } from "../../fixtures";

test("A field the parser cannot read gets a null value and low confidence", { tag: "@DOC-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const vendor = await factory.vendor({ as: "member" });
  const document = await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate_unparseable.txt", "member");

  // Act: extraction runs in the background, so wait for the document to finish processing.
  await expect
    .poll(
      async () => {
        const current = await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200);
        return current.status;
      },
      { message: "extraction finishes for the insurance certificate", timeout: 30_000 },
    )
    .toBe("extracted");

  // Assert: re-read the stored extraction rather than trusting any earlier response.
  const extraction = await factory.extraction(document.id, "member");
  expect(extraction.status, "extraction awaits review").toBe("pending_review");
  const expiry = (extraction as unknown as { fields: Record<string, { value: string | null; confidence: number }> }).fields.expiry_date;
  expect(expiry, "expiry_date field is present").toBeDefined();
  expect(expiry.value, "unparseable expiry date has no value").toBeNull();
  expect(expiry.confidence, "unparseable expiry date has confidence below 0.5").toBeLessThan(0.5);
});
